from __future__ import annotations

import hashlib
import json
import os
import re
import subprocess
from pathlib import Path
from typing import Any

# Layout modelled on Sam_Kim_resume_dec2027.pdf: role-first two-row entries,
# TeX Gyre Termes, small-caps section rules, and a calmer page frame.
PREAMBLE = r"""%-------------------------
% Resume in Latex
% Generated by the hunt CLI from resume JSON. Do not edit by hand.
%------------------------

\documentclass[letterpaper,10pt]{article}

% The reference uses the TeX Gyre Termes family, a clean Times-compatible face.
\usepackage{tgtermes}
\usepackage[T1]{fontenc}
\usepackage{latexsym}
\usepackage[empty]{fullpage}
\usepackage{titlesec}
\usepackage{marvosym}
\usepackage[usenames,dvipsnames]{color}
\usepackage{enumitem}
\usepackage[hidelinks]{hyperref}
\usepackage{fancyhdr}
\usepackage[english]{babel}
\usepackage{tabularx}
\input{glyphtounicode}

\pagestyle{fancy}
\fancyhf{}
\fancyfoot{}
\renewcommand{\headrulewidth}{0pt}
\renewcommand{\footrulewidth}{0pt}
\setlength{\footskip}{12pt}

% Adjust margins
\addtolength{\oddsidemargin}{-0.5in}
\addtolength{\evensidemargin}{-0.5in}
\addtolength{\textwidth}{1.0in}
\addtolength{\topmargin}{-.5in}
\addtolength{\textheight}{1.0in}

\urlstyle{same}
\raggedbottom
\raggedright
\setlength{\tabcolsep}{0in}

% The reference uses light small-caps labels over thin full-width rules.
% The rule underlines the label, so it sits at the glyph bottom and must not be
% shifted. The space after it is what gives the first entry heading clearance.
% The 4.6pt after-space reproduces the reference's 6.4pt gap between the rule
% and the first entry heading. It is paid for out of the space above the label,
% which the reference spends less carefully than the space below it.
\titleformat{\section}{\large\scshape\raggedright}{}{0em}{}[\titlerule]
\titlespacing*{\section}{0pt}{3.5pt}{4.6pt}

\pdfgentounicode=1

%-------------------------
% Custom commands
\newcommand{\resumeItem}[1]{
  \item #1
}

% Keyword emphasis inside bullets. Bold carries the emphasis; the sans family
% and matched optical size keep it from competing with the serif bold entry
% headings, which is what plain \textbf at body size did.
\newcommand{\resumeKeyword}[1]{{\fontfamily{lmss}\selectfont\footnotesize\bfseries #1}}

% Two-row entry heading: role and date, then organization and location.
\newcommand{\resumeEntry}[4]{
  \item
  \begin{tabular*}{\linewidth}[t]{l@{\extracolsep{\fill}}r}
    \textbf{#1} & #2 \\[2pt]
    \textit{#3} & \textit{#4} \\
  \end{tabular*}\vspace{1pt}
}

% Single-row heading for entries that carry no separate role or location.
\newcommand{\resumeHeading}[2]{
  \item
  \begin{tabular*}{\linewidth}[t]{l@{\extracolsep{\fill}}r}
    \textbf{#1} & #2 \\
  \end{tabular*}\vspace{1pt}
}

\newcommand{\resumeSkill}[2]{
  \item \textbf{#1:} #2
}

% Entries hang indented under the section label rather than sitting flush with
% it, and bullets indent again from the entry. The reference puts the label at
% the margin, entries 10.8pt in, and bullets 25.5pt in. Right edges are
% unaffected: leftmargin shrinks \linewidth, so the dates still reach the margin.
\newcommand{\resumeSubHeadingListStart}{\begin{itemize}[leftmargin=10.8pt, label={},%
  itemsep=0pt, topsep=1pt, parsep=0pt]}
\newcommand{\resumeSubHeadingListEnd}{\end{itemize}}
\newcommand{\resumeItemListStart}{\begin{itemize}[leftmargin=23.2pt, label=\textbullet,%
  itemsep=1.7pt, topsep=5pt, parsep=0pt]}
\newcommand{\resumeItemListEnd}{\end{itemize}\vspace{-3.8pt}}
"""

REPRODUCIBLE_EPOCH = "946684800"  # 2000-01-01T00:00:00Z

# A resume build is valid only when the reference-style layout stays on one page.
MAXIMUM_PAGES: int | None = 1


def latex_environment() -> dict[str, str]:
    environment = os.environ.copy()
    environment["SOURCE_DATE_EPOCH"] = REPRODUCIBLE_EPOCH
    environment["FORCE_SOURCE_DATE"] = "1"
    return environment


def compile_resume(resume: dict[str, Any], output_directory: Path) -> Path:
    output_directory.mkdir(parents=True, exist_ok=True)
    source = output_directory / "resume.tex"
    source.write_text(build_latex(resume), encoding="utf-8")
    process = subprocess.run(
        [
            "latexmk",
            "-pdf",
            "-interaction=nonstopmode",
            "-halt-on-error",
            f"-outdir={output_directory}",
            str(source),
        ],
        check=False,
        capture_output=True,
        env=latex_environment(),
        text=True,
        timeout=120,
    )
    pdf = output_directory / "resume.pdf"
    if process.returncode != 0 or not pdf.exists():
        raise RuntimeError((process.stdout + "\n" + process.stderr)[-2000:])
    page_check = subprocess.run(
        ["pdfinfo", str(pdf)], check=False, capture_output=True, text=True, timeout=15
    )
    pages = re.search(r"^Pages:\s+(\d+)$", page_check.stdout, re.MULTILINE)
    if page_check.returncode != 0 or pages is None:
        raise RuntimeError("Could not verify the generated resume page count")
    if MAXIMUM_PAGES is not None and int(pages.group(1)) > MAXIMUM_PAGES:
        raise RuntimeError(
            f"Resume must stay within {MAXIMUM_PAGES} page(s); generated {pages.group(1)}"
        )
    return pdf


def build_latex(resume: dict[str, Any]) -> str:
    serialized = json.dumps(resume, sort_keys=True, separators=(",", ":"))
    trailer_id = hashlib.sha256(serialized.encode()).hexdigest()[:32].upper()
    parts = [
        PREAMBLE,
        rf"\pdftrailerid{{<{trailer_id}><{trailer_id}>}}",
        r"\begin{document}",
    ]
    parts.extend(build_header(resume.get("contact", {})))
    parts.extend(build_education(resume.get("education", {})))
    parts.extend(build_entries("Experience", resume.get("experience", [])))
    parts.extend(build_entries("Research", resume.get("research", [])))
    parts.extend(build_entries("Projects", resume.get("projects", [])))
    parts.extend(build_skills(resume.get("skills", [])))
    parts.append(r"\end{document}")
    return "\n".join(parts) + "\n"


def build_header(contact: dict[str, Any]) -> list[str]:
    details: list[str] = []
    citizenship = str(contact.get("citizenship", "")).strip()
    if citizenship:
        details.append(escape(citizenship))
    phone = str(contact.get("phone", "")).strip()
    if phone:
        details.append(escape(phone))
    email = str(contact.get("email", "")).strip()
    if email:
        details.append(rf"\href{{mailto:{email}}}{{\underline{{{escape(email)}}}}}")
    for key in ("linkedin", "github"):
        link = str(contact.get(key, "")).strip()
        if link:
            details.append(rf"\href{{{link}}}{{\underline{{{escape(display_url(link))}}}}}")
    return [
        r"\begin{center}",
        rf"    {{\Huge\scshape {escape(str(contact.get('name', '')))}}} \\ \vspace{{2pt}}",
        r"    \small " + " \\textbar{}\n    ".join(details),
        r"\end{center}",
        r"\vspace{-10pt}",
    ]


def build_education(education: dict[str, Any]) -> list[str]:
    degree = escape(str(education.get("degree", "")))
    threads = escape(str(education.get("threads", "")).strip())
    if threads:
        degree = rf"{degree} \textbar{{}} Threads: {threads}"
    gpa = escape(str(education.get("gpa", "")).strip())
    scale = escape(str(education.get("gpaScale", "")).strip())
    if gpa and scale:
        gpa = f"{gpa}/{scale}"
    if gpa:
        degree = rf"{degree} \textbar{{}} GPA: {gpa}"
    lines = [
        r"\section{Education}",
        r"\resumeSubHeadingListStart",
        r"  \item",
        r"    \begin{tabular*}{\linewidth}{l@{\extracolsep{\fill}}r}",
        (
            rf"      \textbf{{{escape(str(education.get('school', '')))}}} & "
            rf"{escape(str(education.get('location', '')))} \\"
        ),
        (
            rf"      \textit{{{degree}}} & "
            rf"\textit{{{escape(str(education.get('graduation', '')))}}} \\"
        ),
        r"    \end{tabular*}",
    ]
    courses = escape(str(education.get("courses", "")).strip())
    if courses:
        lines.append(rf"    \vspace{{1pt}} \textbf{{Core Coursework:}} {courses}")
    lines.append(r"\resumeSubHeadingListEnd")
    return lines


def build_entries(title: str, entries: list[dict[str, Any]]) -> list[str]:
    """Render one section.

    Every entry follows the reference's role-first hierarchy. The organization,
    lab, award, or venue sits on the italic second row when present.
    """
    lines = [rf"\section{{{title}}}", r"\resumeSubHeadingListStart"]
    for entry in entries:
        role = escape(str(entry.get("title", "")))
        org = escape(str(entry.get("org", "") or ""))
        location = escape(str(entry.get("location", "") or ""))
        date = escape(str(entry.get("date", "")))
        if org:
            lines.append(rf"  \resumeEntry{{{role}}}{{{date}}}{{{org}}}{{{location}}}")
        else:
            lines.append(rf"  \resumeHeading{{{role}}}{{{date}}}")
        lines.append(r"  \resumeItemListStart")
        lines.extend(
            rf"    \resumeItem{{{render(str(bullet))}}}" for bullet in entry.get("bullets", [])
        )
        lines.append(r"  \resumeItemListEnd")
    lines.append(r"\resumeSubHeadingListEnd")
    return lines


def build_skills(skills: list[dict[str, Any]]) -> list[str]:
    if not skills:
        return []
    # Skill items are plain lines, not [t]-aligned tabulars, so they ride higher
    # under the rule than an entry heading does. Recover the difference.
    lines = [
        r"\section{Technical Skills}",
        r"\vspace{4pt}",
        r"\resumeSubHeadingListStart",
    ]
    lines.extend(
        rf"  \resumeSkill{{{escape(str(skill.get('category', '')))}}}"
        rf"{{{escape(str(skill.get('items', '')))}}}"
        for skill in skills
    )
    lines.append(r"\resumeSubHeadingListEnd")
    return lines


def display_url(url: str) -> str:
    return re.sub(r"^https?://(www\.)?", "", url).rstrip("/")


BOLD_MARKUP = re.compile(r"\*\*(?P<text>[^*]+)\*\*")


def render(value: str) -> str:
    """Escape resume text, then promote paired ``**...**`` markers to bold.

    Escaping runs first so authored text can never inject LaTeX; the markers
    survive it untouched because asterisks are not special to TeX. Unpaired
    markers stay literal rather than failing the build.
    """
    return BOLD_MARKUP.sub(lambda match: rf"\resumeKeyword{{{match['text']}}}", escape(value))


def escape(value: str) -> str:
    replacements = {
        "\\": r"\textbackslash{}",
        "&": r"\&",
        "%": r"\%",
        "$": r"\$",
        "#": r"\#",
        "_": r"\_",
        "{": r"\{",
        "}": r"\}",
        "~": r"\textasciitilde{}",
        "^": r"\textasciicircum{}",
        "|": r"\textbar{}",
        "–": "--",  # noqa: RUF001 - the authored en dash intentionally maps to TeX.
        "—": "---",
    }
    return "".join(replacements.get(character, character) for character in value)
